const SECRETARY_PHOTO_SRC = 'data:image/jpeg;base64,';
const PRINCIPAL_PHOTO_SRC = 'data:image/jpeg;base64,';

document.querySelectorAll('[data-secretary-photo]').forEach(image => image.src = SECRETARY_PHOTO_SRC);
document.querySelectorAll('[data-principal-photo]').forEach(image => image.src = PRINCIPAL_PHOTO_SRC);


const hero = document.querySelector('.hero');
const openCurtain = () => { hero.classList.add('open'); document.querySelector('.tap-curtain')?.classList.add('hidden'); };
document.querySelectorAll('.curtain, .tap-curtain').forEach(el => el.addEventListener('click', openCurtain));


const observer = new IntersectionObserver(entries => entries.forEach(entry => {
  if (entry.isIntersecting) entry.target.classList.add('visible');
}), { threshold: .15 });
document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

const closing = document.querySelector('.closing-stage');
const closingObserver = new IntersectionObserver(entries => {
  if (entries[0].isIntersecting) closing.classList.add('close');
}, { threshold: .4 });
closingObserver.observe(closing);

// The homework story starts on its own when it enters view, so nobody has to hunt for a button.
let homeworkPlayed = false;
const homework = document.querySelector('.homework-section');
const homeworkObserver = new IntersectionObserver(entries => {
  if (!entries[0].isIntersecting || homeworkPlayed) return;
  homeworkPlayed = true;
  const text = document.getElementById('searchText');
  const status = document.getElementById('searchStatus');
  setTimeout(() => { text.textContent = 'Homework not in our bags…'; }, 1000);
  setTimeout(() => { status.classList.add('show'); text.textContent = 'Searching our friends’ bags…'; }, 2200);
  setTimeout(() => { text.textContent = 'Still nothing. Think. Think. Think…'; }, 3800);
  setTimeout(() => { status.textContent = 'A very believable explanation has appeared…'; document.getElementById('excuse').classList.add('show'); }, 5200);
}, { threshold: .45 });
homeworkObserver.observe(homework);

document.getElementById('replay').addEventListener('click', () => { window.scrollTo({ top: 0, behavior: 'smooth' }); setTimeout(() => { document.querySelector('.hero').classList.remove('open'); requestAnimationFrame(() => document.querySelector('.hero').classList.add('open')); }, 500); });

// A tiny optional sound cue, created locally so the page has no audio files to load.
let soundOn = false;
const audio = typeof AudioContext !== 'undefined' ? new AudioContext() : null;
document.getElementById('soundToggle').addEventListener('click', () => {
  soundOn = !soundOn;
  document.getElementById('soundToggle').textContent = soundOn ? '♫' : '♪';
  if (soundOn && audio) { const oscillator = audio.createOscillator(), gain = audio.createGain(); oscillator.frequency.value = 660; gain.gain.setValueAtTime(.035, audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + .55); oscillator.connect(gain).connect(audio.destination); oscillator.start(); oscillator.stop(audio.currentTime + .55); }
});
